import { api } from './api.js?release=45c0307-r2';

const app = document.querySelector('#app');
const ui = {
  route: 'dashboard', sidebarOpen: false, customerSearch: '', transactionSearch: '', transactionStatus: 'all', transactionType: 'all',
  walletTab: 'requests', serviceTab: 'catalog', financeRange: 'month', financeUserId: '', supportTab: 'tickets', selectedTicket: null,
  controlsTab: 'provider', selectedWalletUser: '', loginError: '', ticketDetail: null
};

const nav = [
  { section: 'Workspace', items: [['dashboard','Command center','▦'],['customers','Customers','◎'],['wallet','Wallet operations','₦'],['transactions','Transactions','↗']] },
  { section: 'Configure', items: [['services','Services & pricing','◈'],['finance','Financial intelligence','◌']] },
  { section: 'Operate', items: [['support','Support & broadcasts','◔'],['controls','Platform controls','⚙'],['audit','Audit trail','≡']] }
];
const money = value => new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN', maximumFractionDigits: 0 }).format(Number(value || 0));
const number = value => new Intl.NumberFormat('en-NG').format(Number(value || 0));
const shortDate = value => new Date(value).toLocaleString('en-GB', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' });
const initials = name => String(name || 'F').split(' ').map(part => part[0]).join('').slice(0,2).toUpperCase();
const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const kind = value => ({ success:'success', active:'success', approved:'success', resolved:'success', verified:'success', pending:'pending', review:'pending', open:'pending', in_progress:'pending', failed:'danger', suspended:'danger', rejected:'danger', inactive:'danger' }[String(value||'').toLowerCase()] || 'neutral');
const badge = value => `<span class="status ${kind(value)}"><i></i>${esc(String(value || 'unknown').replace('_',' '))}</span>`;
const icon = (mark, tone='') => `<span class="glyph ${tone}">${mark}</span>`;

function toast(title, detail, tone='success') {
  const host = document.querySelector('#toast-region');
  const node = document.createElement('div');
  node.className = `toast ${tone}`;
  node.innerHTML = `<strong>${esc(title)}</strong><span>${esc(detail)}</span>`;
  host.append(node); setTimeout(() => node.remove(), 3800);
}
function openModal(title, subtitle, body, width='medium') {
  closeModal();
  const node = document.createElement('div');
  node.id = 'modal-layer'; node.className = 'modal-layer';
  node.innerHTML = `<button class="modal-backdrop" data-action="close-modal" aria-label="Close dialog"></button><section class="modal ${width}"><header class="modal-head"><div><p>${esc(subtitle || 'ADMINISTRATION')}</p><h2>${title}</h2></div><button class="close-button" data-action="close-modal">×</button></header><div class="modal-content">${body}</div></section>`;
  document.body.append(node);
}
function closeModal(){ document.querySelector('#modal-layer')?.remove(); }
function tabs(key, selected, items){ return `<div class="tabs">${items.map(([value,label])=>`<button class="${selected===value?'active':''}" data-tab="${key}" data-value="${value}">${label}</button>`).join('')}</div>`; }
function empty(title, detail){ return `<div class="empty"><div class="empty-mark">—</div><h3>${title}</h3><p>${detail}</p></div>`; }
function metric(label, value, note, mark, tone='blue'){ return `<article class="metric-card ${tone}"><div class="metric-icon">${mark}</div><div><small>${label}</small><strong>${value}</strong><span>${note}</span></div></article>`; }
function table(headers, body, className=''){ return `<div class="data-card ${className}"><div class="table-wrap"><table><thead><tr>${headers.map(item=>`<th>${item}</th>`).join('')}</tr></thead><tbody>${body || `<tr><td colspan="${headers.length}">${empty('No results found','Adjust a filter or check back later.')}</td></tr>`}</tbody></table></div></div>`; }
function pageHead(kicker, title, copy, actions=''){ return `<header class="page-header"><div><p class="kicker">${kicker}</p><h1>${title}</h1><p class="page-copy">${copy}</p></div><div class="header-actions">${actions}</div></header>`; }

function loginView(){
  return `<main class="login-scene"><div class="login-aurora a"></div><div class="login-aurora b"></div><section class="login-brand"><div class="brand-lockup"><img src="./assets/ferixas-globe.png" alt="Ferixas"/><div><b>FERIXAS</b><span>AsaforVTU</span></div></div><div class="login-intro"><p class="kicker">ADMINISTRATOR CONSOLE</p><h1>Clarity for every<br/>transaction.</h1><p>Operate the complete VTU platform from one secure workspace—customers, liquidity, services, support and financial performance.</p></div><div class="login-trust"><span>●</span> Authenticated administrator access</div></section><section class="login-panel"><div class="login-card"><div class="login-card-top"><p class="kicker">SECURE ACCESS</p><h2>Welcome back</h2><p>Sign in with your authorized administrator account.</p></div><form id="login-form" class="form-stack"><label>Email address<input name="email" type="email" autocomplete="username" placeholder="admin@example.com" required/></label><label>Password<div class="password-wrap"><input name="password" type="password" autocomplete="current-password" placeholder="Enter password" required/><button type="button" class="password-toggle" data-action="toggle-password">Show</button></div></label>${ui.loginError?`<p class="form-error">${esc(ui.loginError)}</p>`:''}<button class="button primary full" type="submit">Sign in to console <span>→</span></button></form></div><p class="login-foot">Ferixas AsaforVTU · Secure administrator access</p></section></main>`;
}
function shell(session, content){
  const active=ui.route;
  return `<div class="console-shell"><aside class="sidebar ${ui.sidebarOpen?'open':''}"><div class="sidebar-top"><button class="brand-lockup sidebar-brand" data-action="navigate" data-route="dashboard"><img src="./assets/ferixas-globe.png" alt="Ferixas"/><div><b>FERIXAS</b><span>Admin console</span></div></button><button class="sidebar-close" data-action="close-sidebar">×</button></div><div class="environment"><span></span> Secure workspace</div><nav class="navigation">${nav.map(group=>`<section><p>${group.section}</p>${group.items.map(([id,label,mark])=>`<button class="nav-link ${active===id?'active':''}" data-action="navigate" data-route="${id}"><i>${mark}</i><span>${label}</span>${id==='support'?'<b class="nav-dot"></b>':''}</button>`).join('')}</section>`).join('')}</nav><div class="sidebar-account"><button class="account-chip" data-action="navigate" data-route="profile"><span>${initials(session.name)}</span><div><b>${esc(session.name)}</b><small>${esc(session.role)}</small></div><i>›</i></button><button class="logout-link" data-action="logout">↙ Sign out</button></div></aside>${ui.sidebarOpen?'<button class="app-backdrop" data-action="close-sidebar"></button>':''}<main class="main-area"><header class="topbar"><button class="mobile-trigger" data-action="open-sidebar">☰</button><div class="crumb"><span>Ferixas Console</span><i>/</i><b>${nav.flatMap(g=>g.items).find(item=>item[0]===active)?.[1] || 'My account'}</b></div><div class="topbar-actions"><button class="light-button" data-action="show-shortcuts">⌘ Quick action</button><button class="avatar" data-action="navigate" data-route="profile">${initials(session.name)}</button></div></header><section class="viewport">${content}</section></main></div>`;
}

async function dashboard(){
  const data=await api.getDashboard();
  const max=Math.max(...data.days.map(item=>item.value),1);
  const recent=data.recent.map(tx=>`<button class="queue-row" data-action="transaction" data-id="${tx.id}"><div>${icon(tx.status==='success'?'✓':'…',kind(tx.status))}</div><div><b>${esc(tx.type)}</b><span>${esc(tx.service)} · ${shortDate(tx.createdAt)}</span></div><strong>${money(tx.amount)}</strong>${badge(tx.status)}<i>›</i></button>`).join('');
  const body=`${pageHead('OPERATIONS OVERVIEW','Command center','A real-time view of the platform, liquidity and active operational work.',`<button class="button secondary" data-action="refresh">↻ Refresh data</button><button class="button primary" data-action="navigate" data-route="wallet">Review funding <span>→</span></button>`)}<section class="metrics-grid">${metric('Active customers',number(data.totalUsers),'Accounts in platform','◎')}${metric('Wallet liquidity',money(data.wallet),'Across main wallets','₦','mint')}${metric("Today’s successful flow",money(data.todaySales),`${data.successRate}% success rate`,'↗','lime')}${metric('Needs review',number(data.pendingFunding+data.openTickets),`${data.pendingFunding} funding · ${data.openTickets} tickets`,'!','orange')}</section><section class="dashboard-grid"><article class="panel chart-panel"><header class="panel-head"><div><p class="kicker">REVENUE FLOW</p><h2>Successful transaction volume</h2></div><span class="range-chip">Last 7 days</span></header><div class="chart-plot">${data.days.map(item=>`<div class="bar-unit"><div class="bar-track"><i style="height:${Math.max(10,Math.round(item.value/max*100))}%"></i></div><span>${item.label}</span></div>`).join('')}</div><footer class="chart-foot"><span>Today</span><b>${money(data.todaySales)}</b><em>Successful value only</em></footer></article><article class="panel health-panel"><header class="panel-head"><div><p class="kicker">PLATFORM HEALTH</p><h2>Operating normally</h2></div>${badge('active')}</header><div class="health-ring"><b>${data.successRate}%</b><span>success rate</span></div><div class="health-list"><div><span>Pending funding</span><b>${data.pendingFunding}</b></div><div><span>Open customer tickets</span><b>${data.openTickets}</b></div></div><button class="text-action" data-action="navigate" data-route="finance">Open financial intelligence →</button></article></section><section class="panel queue-panel"><header class="panel-head"><div><p class="kicker">LIVE QUEUE</p><h2>Recent platform activity</h2></div><button class="text-action" data-action="navigate" data-route="transactions">View all transactions →</button></header><div class="queue-list">${recent}</div></section>`;
  return shell(api.getSession(),body);
}

async function customers(){
  const users=await api.listUsers(); const q=ui.customerSearch.toLowerCase(); const rows=users.filter(user=>`${user.name} ${user.email} ${user.phone}`.toLowerCase().includes(q));
  const body=`${pageHead('CUSTOMER DIRECTORY','Customers','Search and manage account access, verification and wallet entry points.',`<button class="button secondary" data-action="customer-filter">≡ Filter</button><button class="button primary" data-action="open-create-customer">＋ Create customer</button>`)}<section class="toolbar"><label class="search-field">⌕<input data-input="customer-search" placeholder="Search customer, email or phone" value="${esc(ui.customerSearch)}"/></label><div class="toolbar-stats"><span>${number(rows.length)} shown</span><span>${number(users.filter(user=>user.status==='active').length)} active</span></div></section>${table(['Customer','Contact','Wallet','Verification','Status','Actions'],rows.map(user=>`<tr><td><div class="person"><span>${initials(user.name)}</span><div><b>${esc(user.name)}</b><small>${user.id}</small></div></div></td><td><b>${esc(user.email)}</b><small>${esc(user.phone)}</small></td><td><b>${money(user.main)}</b><small>Cashback ${money(user.cashback)}</small></td><td>${user.verified?'<span class="verified">✓ Verified</span>':'<button class="link-button" data-action="verify-user" data-id="'+user.id+'">Send link</button>'}</td><td>${badge(user.status)}</td><td><div class="row-actions"><button data-action="customer" data-id="${user.id}">View</button><button data-action="wallet-for-user" data-id="${user.id}">Wallet</button><button class="more" data-action="customer-menu" data-id="${user.id}">•••</button></div></td></tr>`).join(''))}`;
  return shell(api.getSession(),body);
}
function customerModal(user){
  const finance=user.finance; openModal(esc(user.name),'CUSTOMER PROFILE',`<section class="customer-modal"><div class="customer-hero"><span>${initials(user.name)}</span><div><h3>${esc(user.name)}</h3><p>${esc(user.email)} · ${esc(user.phone)}</p></div>${badge(user.status)}</div><div class="mini-metrics"><div><span>Main wallet</span><b>${money(user.main)}</b></div><div><span>Cashback</span><b>${money(user.cashback)}</b></div><div><span>Referral</span><b>${money(user.referral)}</b></div></div><div class="detail-grid"><div><span>Joined</span><b>${user.joined}</b></div><div><span>Verification</span><b>${user.verified?'Verified':'Pending'}</b></div><div><span>Total successful flow</span><b>${money(finance.deposits)}</b></div><div><span>Generated net</span><b>${money(finance.netProfit)}</b></div></div><div class="modal-actions"><button class="button secondary" data-action="reset-user" data-id="${user.id}">Reset password</button><button class="button secondary" data-action="verify-user" data-id="${user.id}">Verification link</button><button class="button ${user.status==='active'?'danger':''}" data-action="toggle-user" data-id="${user.id}">${user.status==='active'?'Suspend account':'Restore account'}</button></div></section>`,'wide'); }

async function wallet(){
  const [funding,users,transactions]=await Promise.all([api.listFunding(),api.listUsers(),api.listTransactions()]);
  const requests=table(['Request','Customer','Amount','Method','Submitted','Status','Decision'],funding.map(item=>`<tr><td class="mono">${item.id}</td><td><b>${esc(item.user.name)}</b><small>${item.user.email}</small></td><td><b>${money(item.amount)}</b></td><td>${esc(item.method)}</td><td>${shortDate(item.createdAt)}</td><td>${badge(item.status)}</td><td>${['pending','review','processing'].includes(item.status)?`<button class="approve" data-action="funding" data-decision="approved" data-id="${item.id}">Reverify</button>`:'—'}</td></tr>`).join(''));
  const adjustment=`<section class="adjust-grid"><form class="panel form-panel" id="wallet-adjust-form"><div><p class="kicker">MANUAL ADJUSTMENT</p><h2>Credit or debit a wallet</h2></div><div class="form-row two"><label>Customer<select name="userId">${users.map(user=>`<option value="${user.id}" ${ui.selectedWalletUser===user.id?'selected':''}>${esc(user.name)} · ${money(user.main)}</option>`).join('')}</select></label><label>Wallet<select name="walletType"><option value="main">Main wallet</option><option value="cashback">Cashback wallet</option><option value="referral">Referral wallet</option></select></label></div><div class="form-row two"><label>Action<select name="action"><option value="credit">Credit</option><option value="debit">Debit</option></select></label><label>Amount<input name="amount" type="number" min="1" placeholder="0.00" required/></label></div><label>Reason<input name="note" placeholder="Refund, correction or approved promotion" required/></label><button class="button primary" type="submit">Apply wallet adjustment <span>→</span></button></form><article class="panel repair-card"><p class="kicker">DATA INTEGRITY</p><h2>Ghost wallet repair</h2><p>Find customer wallets mapped to legacy identifiers before performing any migration.</p><div class="repair-actions"><button class="button secondary" data-action="repair" data-dry="true">Run dry check</button><button class="button ghost" data-action="repair" data-dry="false">Repair mappings</button></div></article></section>`;
  const logs=table(['Reference','Customer','Operation','Amount','Source','Time'],transactions.filter(tx=>tx.type.includes('Wallet')).map(tx=>`<tr><td class="mono">${tx.reference}</td><td>${esc(tx.user.name)}</td><td>${tx.type}</td><td><b>${money(tx.amount)}</b></td><td>${tx.channel}</td><td>${shortDate(tx.createdAt)}</td></tr>`).join(''));
  const body=`${pageHead('LIQUIDITY MANAGEMENT','Wallet operations','Review funding requests, execute controlled adjustments and inspect wallet activity.',`<button class="button secondary" data-action="navigate" data-route="finance">Open financial intelligence</button>`)}<section class="metrics-grid compact">${metric('Awaiting decision',number(funding.filter(item=>['pending','review'].includes(item.status)).length),'Funding requests in queue','◌','orange')}${metric('Manual adjustments',number(transactions.filter(tx=>tx.channel==='admin').length),'Wallet credit and debit records','₦','mint')}${metric('Wallet operations',number(transactions.filter(tx=>tx.type.includes('Wallet')).length),'Recorded activity','↗','blue')}</section>${tabs('wallet',ui.walletTab,[['requests','Funding requests'],['adjust','Manual adjustment'],['activity','Wallet activity']])}${ui.walletTab==='requests'?requests:ui.walletTab==='adjust'?adjustment:logs}`;
  return shell(api.getSession(),body);
}

async function transactions(){
  const rows=await api.listTransactions({search:ui.transactionSearch,status:ui.transactionStatus,type:ui.transactionType});
  const types=[...new Set((await api.listTransactions()).map(item=>item.type))];
  const body=`${pageHead('TRANSACTION LEDGER','Transactions','Trace every customer funding and VTU fulfilment record from request to outcome.',`<button class="button secondary" data-action="export-transactions">⇩ Export</button>`)}<section class="filter-bar"><label class="search-field">⌕<input data-input="transaction-search" placeholder="Search reference, customer or service" value="${esc(ui.transactionSearch)}"/></label><select data-change="transaction-status"><option value="all">All statuses</option>${['success','pending','failed'].map(value=>`<option value="${value}" ${ui.transactionStatus===value?'selected':''}>${value[0].toUpperCase()+value.slice(1)}</option>`).join('')}</select><select data-change="transaction-type"><option value="all">All transaction types</option>${types.map(value=>`<option value="${esc(value)}" ${ui.transactionType===value?'selected':''}>${esc(value)}</option>`).join('')}</select></section>${table(['Reference','Customer','Service','Amount','Channel','Created','Status',''],rows.map(tx=>`<tr><td><b class="mono">${tx.reference}</b><small>${tx.id}</small></td><td>${esc(tx.user.name)}</td><td><b>${esc(tx.type)}</b><small>${esc(tx.service)}</small></td><td><b>${money(tx.amount)}</b></td><td>${esc(tx.channel)}</td><td>${shortDate(tx.createdAt)}</td><td>${badge(tx.status)}</td><td><div class="row-actions"><button data-action="receipt" data-id="${tx.id}">Receipt</button><button class="more" data-action="transaction" data-id="${tx.id}">Details</button></div></td></tr>`).join(''))}`;
  return shell(api.getSession(),body);
}
function transactionModal(tx, receipt=false){
  if(receipt){ openModal('Transaction receipt','TRANSACTION RECORD',`<section class="receipt-view"><div class="receipt-logo"><img src="./assets/ferixas-globe.png" alt="Ferixas"/><b>FERIXAS</b></div><h3>${money(tx.amount)}</h3>${badge(tx.status)}<dl><div><dt>Reference</dt><dd>${tx.reference}</dd></div><div><dt>Customer</dt><dd>${esc(tx.user.name)}</dd></div><div><dt>Service</dt><dd>${esc(tx.service)}</dd></div><div><dt>Channel</dt><dd>${esc(tx.channel)}</dd></div><div><dt>Created</dt><dd>${shortDate(tx.createdAt)}</dd></div></dl><p>This record is sourced from the authenticated transaction service.</p></section>`); return; }
  openModal('Transaction details','FULL TRANSACTION TRACE',`<section class="detail-modal"><div class="detail-summary"><div><span>Amount</span><b>${money(tx.amount)}</b></div><div><span>Status</span>${badge(tx.status)}</div><div><span>Recipient</span><b>${tx.recipient||'—'}</b></div></div><dl class="detail-grid"><div><dt>ID</dt><dd>${tx.id}</dd></div><div><dt>Reference</dt><dd>${tx.reference}</dd></div><div><dt>Customer</dt><dd>${esc(tx.user.name)}</dd></div><div><dt>Service</dt><dd>${esc(tx.service)}</dd></div><div><dt>Provider cost</dt><dd>${money(tx.providerCost)}</dd></div><div><dt>SMS cost</dt><dd>${money(tx.smsCost)}</dd></div><div><dt>Net contribution</dt><dd>${money(tx.amount-tx.providerCost-tx.smsCost)}</dd></div><div><dt>Failure source</dt><dd>${tx.failureSource||'—'}</dd></div><div><dt>Failure reason</dt><dd>${tx.failureReason||'—'}</dd></div></dl><div class="raw-box"><p>Provider diagnostics</p><pre>Detailed provider payloads are protected by the backend and are not exposed in the browser.</pre></div></section>`,'wide'); }

async function services(){
  const [services,networks,plans]=await Promise.all([api.listServices(),api.listNetworks(),api.listPlans()]);
  let content='';
  if(ui.serviceTab==='catalog') content=table(['Service','Category','Availability','Actions'],services.map(item=>`<tr><td><b>${esc(item.name)}</b><small>${item.id}</small></td><td>${esc(item.category)}</td><td>${badge(item.active?'active':'inactive')}</td><td><button class="toggle ${item.active?'on':''}" data-action="service-toggle" data-id="${item.id}"><i></i></button></td></tr>`).join(''));
  if(ui.serviceTab==='airtime') content=table(['Network','Customer discount','Availability','Action'],networks.map(item=>`<tr><td><b>${item.name}</b></td><td>${item.discount}%</td><td>${badge(item.active?'active':'inactive')}</td><td><button class="button tiny" data-action="network-edit" data-name="${item.name}">Edit network</button></td></tr>`).join(''));
  if(['data','cable','power'].includes(ui.serviceTab)){ const map={data:'Data plans',cable:'Cable TV packages',power:'Electricity providers'}; const groupPlans=plans.filter(item=>item.group===ui.serviceTab); content=`<div class="sub-toolbar"><div><p class="kicker">${map[ui.serviceTab].toUpperCase()}</p><span>${groupPlans.length} configured plans</span></div><div><button class="button primary" data-action="open-plan" data-group="${ui.serviceTab}">＋ Add plan</button></div></div>${table(['Network','Plan','Customer price','Provider cost','Margin','Status','Actions'],groupPlans.map(item=>`<tr><td><b>${esc(item.network)}</b></td><td>${esc(item.name)}<small>${item.variation}</small></td><td>${money(item.userPrice)}</td><td>${money(item.apiPrice)}</td><td class="profit">${money(item.userPrice-item.apiPrice)}</td><td>${badge(item.active?'active':'inactive')}</td><td><button class="button tiny" data-action="plan-edit" data-id="${item.id}">Edit</button></td></tr>`).join(''))}`; }
  const body=`${pageHead('PRODUCT CONFIGURATION','Services & pricing','Control availability, retail pricing and upstream plan mappings.',`<button class="button secondary" data-action="open-service">＋ Add service</button>`)}${tabs('service',ui.serviceTab,[['catalog','Service catalog'],['airtime','Airtime'],['data','Data'],['cable','Cable TV'],['power','Electricity']])}${content}`;
  return shell(api.getSession(),body);
}

async function finance(){
  const finance=await api.getFinance({range:ui.financeRange,userId:ui.financeUserId});
  const users=ui.financeUserId?await api.listUsers():[];
  const max=Math.max(...finance.dateSeries.map(item=>Math.abs(item.value)),1); const selected=finance.user;
  const risk=selected?`<section class="customer-risk"><div><p class="kicker">CUSTOMER FINANCIAL RISK</p><h2>${esc(selected.name)}</h2><p>Customer-specific profitability and transaction capacity based on active plan costs.</p></div><div class="risk-values"><div><span>Customer wallet</span><b>${money(finance.customerFinance.walletBalance)}</b></div><div><span>Expected net</span><b>${money(finance.customerFinance.risk.expectedProfit)}</b></div><div><span>Provider obligation</span><b>${money(finance.customerFinance.risk.providerBalanceRequired)}</b></div></div></section>`:'';
  const rows=finance.transactions.map(tx=>`<tr><td><b class="mono">${tx.id}</b><small>${shortDate(tx.createdAt)}</small></td><td>${esc(tx.user.name)}</td><td><b>${esc(tx.type)}</b><small>${esc(tx.service)}</small></td><td>${money(tx.amount)}</td><td>${money(tx.providerCost)}</td><td>${money(tx.smsCost)}</td><td class="profit">${money(tx.net)}</td><td>${tx.status==='failed'?`<span class="failure">${tx.failureSource||'unknown'}<small>${tx.failureReason||'No reason'}</small></span>`:badge(tx.status)}</td></tr>`).join('');
  const periodRows=finance.period.map(item=>`<tr><td><b>${item.label[0].toUpperCase()+item.label.slice(1)}</b></td><td>${money(item.deposits)}</td><td>${money(item.providerCost)}</td><td>${money(item.smsCost)}</td><td class="profit">${money(item.netProfit)}</td><td>${number(item.transactionCount)}</td></tr>`).join('');
  const body=`${pageHead('FINANCIAL INTELLIGENCE','Financial intelligence','Understand successful flow, cost exposure, profitability and transaction-level exceptions.',`<button class="button secondary" data-action="finance-export">⇩ Export report</button>`)}<section class="intel-controls"><div class="scope-switch"><button class="${!ui.financeUserId?'active':''}" data-action="finance-scope" data-value="">System view</button><button class="${ui.financeUserId?'active':''}" data-action="finance-customer">Customer view</button></div><label>Reporting period<select data-change="finance-range"><option value="day" ${ui.financeRange==='day'?'selected':''}>Today</option><option value="week" ${ui.financeRange==='week'?'selected':''}>Last 7 days</option><option value="month" ${ui.financeRange==='month'?'selected':''}>This month</option><option value="all" ${ui.financeRange==='all'?'selected':''}>All recorded data</option></select></label>${ui.financeUserId?`<label>Customer<select data-change="finance-user">${users.map(user=>`<option value="${user.id}" ${ui.financeUserId===user.id?'selected':''}>${esc(user.name)} · ${user.email}</option>`).join('')}</select></label>`:''}</section><section class="finance-hero"><div><p class="kicker">${finance.scope==='system'?'SYSTEM FINANCIAL POSITION':'CUSTOMER FINANCIAL POSITION'}</p><h2>${money(finance.totals.deposits)}</h2><p>Successful transaction flow in the selected period.</p></div><div class="finance-hero-meta"><div><span>Gross successful flow</span><b>${money(finance.totals.deposits)}</b></div><div><span>Net contribution</span><b>${money(finance.totals.netProfit)}</b></div></div></section><section class="metrics-grid finance-metrics">${metric('Provider obligation',money(finance.providerBalanceRequired),'Cumulative provider cost exposure','◌','orange')}${metric('Wallet liquidity',money(finance.walletBalance),selected?'Selected customer main wallet':'Total customer main wallets','₦','mint')}${metric('Provider cost',money(finance.totals.providerCost),'Successful period cost','↓','blue')}${metric('SMS cost',money(finance.totals.smsCost),'Successful period messaging','✦','purple')}${metric('Net profit',money(finance.totals.netProfit),'After upstream and SMS costs','↗','lime')}</section><section class="finance-grid"><article class="panel performance-card"><header class="panel-head"><div><p class="kicker">NET CONTRIBUTION</p><h2>Seven-day trend</h2></div><span class="range-chip">${ui.financeRange==='all'?'All data':'Current context'}</span></header><div class="area-chart">${finance.dateSeries.map(item=>`<div><i style="height:${Math.max(8,Math.abs(item.value)/max*100)}%"></i><span>${item.label}</span></div>`).join('')}</div><footer><span>Based on successful transactions only</span><b>${money(finance.totals.netProfit)} net</b></footer></article><article class="panel period-card"><header class="panel-head"><div><p class="kicker">PERIOD PERFORMANCE</p><h2>Daily · weekly · monthly</h2></div></header>${table(['Period','Flow','Provider','SMS','Net','Count'],periodRows,'inside-table')}</article></section>${risk}<section class="panel ledger-panel"><header class="panel-head"><div><p class="kicker">MARGIN LEDGER</p><h2>Financial transaction breakdown</h2><span>Failure source and reason remain visible for exceptions.</span></div><button class="text-action" data-action="navigate" data-route="transactions">Open transaction ledger →</button></header>${table(['ID / time','Customer','Service','User price','Provider cost','SMS','Net','Outcome or failure'],rows,'inside-table')}</section>${selected?`<section class="panel capacity-panel"><header class="panel-head"><div><p class="kicker">CUSTOMER PURCHASE CAPACITY</p><h2>Active-plan capacity at API cost</h2></div></header>${table(['Active plan','API cost','Estimated transactions'],finance.capacity.map(item=>`<tr><td>${esc(item.service)}</td><td>${money(item.apiPrice)}</td><td><b>${number(item.capacity)}</b></td></tr>`).join(''),'inside-table')}</section>`:''}`;
  return shell(api.getSession(),body);
}

async function support(){
  const [tickets,announcements]=await Promise.all([api.listTickets(),api.listAnnouncements()]);
  const selected=(ui.ticketDetail && ui.ticketDetail.id===ui.selectedTicket) ? ui.ticketDetail : tickets.find(ticket=>ticket.id===ui.selectedTicket);
  const ticketsView=`<section class="support-layout"><div class="ticket-list">${tickets.map(ticket=>`<button class="ticket-row ${selected?.id===ticket.id?'active':''}" data-action="ticket" data-id="${ticket.id}"><span class="ticket-initial">${initials(ticket.user.name)}</span><div><b>${esc(ticket.subject)}</b><small>${esc(ticket.user.name)} · ${shortDate(ticket.updatedAt)}</small></div>${badge(ticket.status)}</button>`).join('')}</div><section class="panel thread-panel">${selected?`<header class="thread-head"><div><p class="kicker">${selected.id}</p><h2>${esc(selected.subject)}</h2><span>${esc(selected.user.name)} · ${esc(selected.user.email)}</span></div><select data-change="ticket-status"><option value="open" ${selected.status==='open'?'selected':''}>Open</option><option value="in_progress" ${selected.status==='in_progress'?'selected':''}>In progress</option><option value="resolved" ${selected.status==='resolved'?'selected':''}>Resolved</option></select><button class="more" data-action="delete-ticket" data-id="${selected.id}">Delete</button></header><div class="thread">${selected.messages.map(message=>`<article class="message ${message.author==='admin'?'outgoing':''}"><span>${message.author==='admin'?initials(api.getSession().name):initials(selected.user.name)}</span><div><b>${message.author==='admin'?'You':selected.user.name}</b><p>${esc(message.text)}</p><small>${shortDate(message.createdAt)}</small></div></article>`).join('')}</div><form id="ticket-reply-form" class="reply-form"><textarea name="message" placeholder="Write a clear reply to the customer…" required></textarea><button class="button primary" type="submit">Send reply <span>→</span></button></form>`:empty('Select a ticket','Choose a customer ticket to see its full thread.')}</section></section>`;
  const broadcasts=`<section class="broadcast-layout"><div class="broadcast-create"><article class="panel form-panel"><p class="kicker">NEW BROADCAST</p><h2>Publish an announcement</h2><form id="announcement-form" class="form-row"><label>Title<input name="title" placeholder="Announcement title" required/></label><label>Message<textarea name="content" placeholder="Brief customer-facing update" required></textarea></label><label>Type<select name="type"><option value="info">Information</option><option value="warning">Service advisory</option></select></label><button class="button primary" type="submit">Publish announcement <span>→</span></button></form></article></div><div class="announcement-list">${announcements.map(item=>`<article class="announcement"><div class="announcement-type ${item.type}">${item.type==='warning'?'!':'i'}</div><div><h3>${esc(item.title)}</h3><p>${esc(item.content)}</p><small>${shortDate(item.createdAt)}</small></div><button class="more" data-action="delete-announcement" data-id="${item.id}">×</button></article>`).join('')}</div></section>`;
  const body=`${pageHead('CUSTOMER COMMUNICATION','Support & broadcasts','Resolve customer cases in context and publish concise service updates.')}${tabs('support',ui.supportTab,[['tickets','Support inbox'],['broadcasts','Broadcasts']])}${ui.supportTab==='tickets'?ticketsView:broadcasts}`;
  return shell(api.getSession(),body);
}

const fundingAccountRows = accounts => (accounts || []).map((account, index) => `<div class="manual-account-row" data-manual-account-row><div class="form-row two"><label>Bank name<input data-account-field="bank_name" value="${esc(account.bank_name || '')}" placeholder="Opay, UBA, etc."/></label><label>Account name<input data-account-field="account_name" value="${esc(account.account_name || '')}" placeholder="Account holder name"/></label></div><div class="form-row two"><label>Account number<input data-account-field="account_number" value="${esc(account.account_number || '')}" inputmode="numeric" placeholder="Account number"/></label><label class="checkbox"><input type="checkbox" data-account-field="enabled" ${account.enabled !== false ? 'checked' : ''}/> Available to customers</label></div><button type="button" class="text-action" data-action="remove-manual-account">Remove this account</button></div>`).join('');
async function controls(){
  const settings=await api.getSettings();
  const admins=ui.controlsTab==='admins'?await api.listAdmins():[];
  const manualAccounts=settings.manualAccounts?.length?settings.manualAccounts:(settings.manualBankName&&settings.manualAccountName&&settings.manualAccountNumber?[{id:'legacy-primary',bank_name:settings.manualBankName,account_name:settings.manualAccountName,account_number:settings.manualAccountNumber,enabled:true}]:[]);
  const provider=`<section class="controls-grid"><form id="settings-form" class="panel form-panel"><div><p class="kicker">PROGRAMME CONTROLS</p><h2>Platform safeguards</h2><p>Provider credentials and inbound webhook addresses are protected server-side and are not displayed in the administrator browser.</p></div><div class="toggle-line"><div><b>Automated wallet funding</b><span>Allow customers to open Flutterwave checkout</span></div><button type="button" class="toggle ${settings.automatedFundingEnabled?'on':''}" data-action="funding-toggle"><i></i></button><input type="hidden" name="automatedFundingEnabled" value="${settings.automatedFundingEnabled}"/></div><div class="toggle-line"><div><b>Cashback programme</b><span>Enable cashback ledger and rewards</span></div><button type="button" class="toggle ${settings.cashbackEnabled?'on':''}" data-action="setting-toggle"><i></i></button><input type="hidden" name="cashbackEnabled" value="${settings.cashbackEnabled}"/></div><label>Daily referral budget<input name="referralBudget" type="number" min="0" value="${settings.referralBudget}" required/></label><div class="form-row two"><label>Referral campaign starts<input name="referralCampaignStartAt" type="datetime-local" value="${String(settings.referralCampaignStartAt||'').slice(0,16)}"/></label><label>Referral campaign ends<input name="referralCampaignEndAt" type="datetime-local" value="${String(settings.referralCampaignEndAt||'').slice(0,16)}"/></label></div><p class="form-note">Outside this window, referrals remain recorded but no bonus is paid and no purchase error is shown.</p><section class="manual-accounts-editor"><header><div><b>Manual bank accounts</b><span>Add every account customers may use. Disabled accounts are hidden from customers.</span></div><button type="button" class="button secondary" data-action="add-manual-account">＋ Add account</button></header><div id="manual-accounts-list">${fundingAccountRows(manualAccounts)}</div><p class="form-note">Customers choose one active account and can copy its details before contacting you.</p></section><div class="form-row two"><label>WhatsApp support number<input name="manualWhatsappNumber" value="${esc(settings.manualWhatsappNumber||'')}" inputmode="tel" placeholder="e.g. 08012345678"/></label><label>Manual funding instructions<input name="manualFundingInstructions" value="${esc(settings.manualFundingInstructions||'')}" placeholder="Transfer and contact Support"/></label></div><p class="form-note">When automated funding is disabled, customers see these details instead of Flutterwave checkout. Their wallet is credited only after administrator review.</p><button class="button primary" type="submit">Save platform controls <span>→</span></button></form><article class="panel webhook-card"><p class="kicker">PAYMENT WEBHOOK</p><h2>Protected backend receiver</h2><p>Payment status callbacks are received and validated by the backend. The endpoint and its credentials are intentionally never exposed in this dashboard.</p><div class="webhook-note"><i>✓</i><span>Backend-controlled webhook validation is active.</span></div></article></section>`;
  const payments=`<section class="controls-grid payments"><article class="panel reconcile-card"><p class="kicker">PAYMENT RECONCILIATION</p><h2>Confirm a payment reference</h2><p>Use only when a provider callback needs an administrator review.</p><form id="reconcile-form" class="reconcile-form"><input name="reference" placeholder="Reference or transaction ID" required/><label class="checkbox"><input type="checkbox" name="force"/> Force reconciliation when previously recorded</label><button class="button primary" type="submit">Reconcile payment <span>→</span></button></form></article><article class="panel referral-card"><p class="kicker">REFERRAL PROGRAMME</p><h2>Budget safeguard</h2><p>Rewards remain subject to the configured daily payout budget.</p><b>${money(settings.referralBudget)} <small>daily allocation</small></b><button class="button secondary" data-action="navigate" data-route="finance">Review financial impact</button></article></section>`;
  const adminsView=`<section class="panel"><header class="panel-head"><div><p class="kicker">ADMINISTRATOR ACCESS</p><h2>Console administrators</h2></div><button class="button primary" data-action="open-admin">＋ Invite administrator</button></header>${table(['Administrator','Email','Role','Status'],admins.map(admin=>`<tr><td><div class="person"><span>${initials(admin.name)}</span><b>${esc(admin.name)}</b></div></td><td>${esc(admin.email)}</td><td>${esc(admin.role)}</td><td>${badge(admin.status)}</td></tr>`).join(''),'inside-table')}</section>`;
  const body=`${pageHead('PLATFORM CONTROLS','Platform controls','Configure provider access, payment recovery and administrative access.',`<button class="button secondary" data-action="navigate" data-route="audit">View audit trail</button>`)}${tabs('controls',ui.controlsTab,[['provider','Provider & webhook'],['payments','Payments & referral'],['admins','Administrators']])}${ui.controlsTab==='provider'?provider:ui.controlsTab==='payments'?payments:adminsView}`;
  return shell(api.getSession(),body);
}

async function audit(){
  const rows=await api.listAudit();
  const body=`${pageHead('PLATFORM ACCOUNTABILITY','Audit trail','Review administrator-originated actions and configuration changes.',`<button class="button secondary" data-action="audit-filter">≡ Filter events</button>`)}<section class="audit-summary"><div><span>Server-recorded events</span><b>${number(rows.length)} recorded events</b></div><p>Events are read from the protected administrative audit log.</p></section>${table(['Time','Action','Administrator','Details','Outcome'],rows.map(item=>`<tr><td class="mono">${shortDate(item.createdAt)}</td><td><b>${esc(item.action)}</b></td><td>${esc(item.actor)}</td><td>${esc(item.detail)}</td><td>${badge(item.level==='warning'?'pending':'success')}</td></tr>`).join(''))}`;
  return shell(api.getSession(),body);
}

async function profile(){
  const session=api.getSession(); const body=`${pageHead('ACCOUNT SETTINGS','My account','Manage your authenticated administrator identity and security settings.')}<section class="profile-layout"><article class="profile-card"><span class="profile-avatar">${initials(session.name)}</span><h2>${esc(session.name)}</h2><p>${esc(session.email)}</p>${badge('active')}<dl><div><dt>Role</dt><dd>${esc(session.role)}</dd></div><div><dt>Session started</dt><dd>${shortDate(session.signedInAt)}</dd></div><div><dt>Access</dt><dd>Authenticated</dd></div></dl></article><form id="profile-form" class="panel form-panel"><div><p class="kicker">PROFILE DETAILS</p><h2>Administrator profile</h2></div><div class="form-row two"><label>Display name<input name="name" value="${esc(session.name)}" required/></label><label>Phone number<input name="phone" value="${esc(session.phone || '')}" required/></label></div><label>Authenticated email<input value="${esc(session.email)}" disabled/></label><button class="button primary" type="submit">Save profile <span>→</span></button></form></section><form id="password-form" class="panel security-panel"><div><p class="kicker">ACCOUNT SECURITY</p><h2>Change password</h2><p>Your password change is sent securely to the authenticated backend.</p></div><div class="form-row three"><label>Current password<input type="password" name="currentPassword" required/></label><label>New password<input type="password" name="newPassword" minlength="8" required/></label><label>Confirm password<input type="password" name="confirmPassword" minlength="8" required/></label></div><button class="button secondary" type="submit">Update password</button></form>`;
  return shell(session,body);
}

const routes={dashboard,customers,wallet,transactions,services,finance,support,controls,audit,profile};
async function render(){ const session=api.getSession(); if(!session){app.innerHTML=loginView(); return;} app.innerHTML='<div class="loading-state"><span></span></div>'; try { app.innerHTML=await (routes[ui.route]||dashboard)(); } catch (error) { if(/session has expired/i.test(error.message || '')) { ui.loginError='Your session has expired. Please sign in again.'; app.innerHTML=loginView(); return; } app.innerHTML=`<main class="error-state"><section><p class="kicker">ADMINISTRATOR CONSOLE</p><h1>We could not load this workspace.</h1><p>Check your connection or try again. No cached or fallback records are displayed.</p><button class="button primary" data-action="refresh">Try again</button></section></main>`; } }

async function handleAction(action, data, element){
  if(action==='navigate'){ui.route=data.route;ui.sidebarOpen=false;ui.selectedTicket=null;ui.ticketDetail=null;render();return;}
  if(action==='open-sidebar'){ui.sidebarOpen=true;render();return;}
  if(action==='close-sidebar'){ui.sidebarOpen=false;render();return;}
  if(action==='logout'){await api.logout();ui.loginError='';render();return;}
  if(action==='refresh'){toast('Workspace refreshed','Live administrative data has been reloaded.');render();return;}
  if(action==='toggle-password'){const input=element.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';element.textContent=input.type==='password'?'Show':'Hide';return;}
  if(action==='show-shortcuts'){openModal('Quick action','ADMINISTRATOR SHORTCUTS',`<div class="quick-grid"><button data-action="navigate" data-route="wallet">Wallet adjustment</button><button data-action="navigate" data-route="transactions">Find transaction</button><button data-action="navigate" data-route="support">Open support inbox</button><button data-action="navigate" data-route="finance">Financial intelligence</button></div>`);return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='customer'){customerModal(await api.getUser(data.id));return;}
  if(action==='customer-menu'){const user=await api.getUser(data.id);openModal(esc(user.name),'ACCOUNT ACTIONS',`<div class="quick-grid"><button data-action="reset-user" data-id="${user.id}">Reset password</button><button data-action="verify-user" data-id="${user.id}">Issue verification link</button><button data-action="toggle-user" data-id="${user.id}">${user.status==='active'?'Suspend account':'Restore account'}</button></div>`);return;}
  if(action==='wallet-for-user'){ui.selectedWalletUser=data.id;ui.route='wallet';ui.walletTab='adjust';render();return;}
  if(action==='toggle-user'){const user=await api.setUserStatus(data.id,(await api.getUser(data.id)).status!=='active');closeModal();toast('Customer access updated',`${user.name} is now ${user.status}.`,user.status==='active'?'success':'pending');render();return;}
  if(action==='verify-user'){const result=await api.issueVerification(data.id);closeModal();toast('Verification link created',result.link,'success');render();return;}
  if(action==='reset-user'){await api.resetUserPassword(data.id);closeModal();toast('Reset initiated','A password-reset email has been requested for this customer.','pending');return;}
  if(action==='open-create-customer'){openModal('Create customer','CUSTOMER ENROLMENT',`<form id="create-customer-form" class="form-row"><label>Full name<input name="name" required/></label><label>Email<input name="email" type="email" required/></label><label>Phone number<input name="phone" required/></label><label>Temporary password<input name="password" type="password" autocomplete="new-password" minlength="8" required/></label><button class="button primary" type="submit">Create customer <span>→</span></button></form>`);return;}
  if(action==='customer-filter'){toast('Directory filters','The live adapter will add server-side role, status and date filters.','pending');return;}
  if(action==='funding'){try{await api.decideFunding(data.id,data.decision);toast('Payment reverification requested',`Funding reference ${data.id} has been submitted for backend reconciliation.`,'pending');render();}catch(error){toast('Funding action unavailable',error.message,'danger');}return;}
  if(action==='repair'){const result=await api.ghostWalletRepair(data.dry==='true');toast(result.dryRun?'Dry check complete':'Repair complete',result.dryRun?`${result.candidates} candidate mappings detected.`:`${result.repaired} wallet mapping(s) repaired.`,result.dryRun?'pending':'success');return;}
  if(action==='export-transactions'||action==='finance-export'){toast('Export unavailable','A verified server-side export endpoint is required. No file was created.','pending');return;}
  if(action==='transaction'||action==='receipt'){transactionModal(await api.getTransaction(data.id),action==='receipt');return;}
  if(action==='service-toggle'){const services=await api.listServices();const item=services.find(x=>x.id===data.id);await api.updateService(data.id,{active:!item.active});toast('Service availability updated',`${item.name} is now ${!item.active?'active':'inactive'}.`);render();return;}
  if(action==='network-edit'){const networks=await api.listNetworks();const item=networks.find(x=>x.name===data.name);openModal(`${item.name} airtime`,'NETWORK CONFIGURATION',`<form id="network-form" class="form-row"><input type="hidden" name="name" value="${item.name}"/><label>Customer discount (%)<input name="discount" type="number" step="0.1" value="${item.discount}" required/></label><label class="toggle-line"><span><b>Availability</b><small>Allow customer purchases</small></span><select name="active"><option value="true" ${item.active?'selected':''}>Active</option><option value="false" ${!item.active?'selected':''}>Inactive</option></select></label><button class="button primary" type="submit">Save network</button></form>`);return;}
  if(action==='plan-edit'){const plans=await api.listPlans();const item=plans.find(x=>x.id===data.id);openPlanModal(item);return;}
  if(action==='open-plan'){openPlanModal(null,data.group);return;}
  if(action==='sync-plans'){const result=await api.syncPlans(data.group);toast('Provider synchronisation complete',`${result.synced} ${data.group} plan mappings refreshed.`);return;}
  if(action==='open-service'){openModal('Add service category','SERVICE CATALOG',`<form id="service-form" class="form-row"><label>Name<input name="name" required/></label><label>Category<select name="category"><option>Airtime & Data</option><option>Bills</option><option>Education</option></select></label><button class="button primary" type="submit">Create service</button></form>`);return;}
  if(action==='finance-scope'){ui.financeUserId=data.value;render();return;}
  if(action==='finance-customer'){const users=await api.listUsers();openModal('Choose customer','CUSTOMER FINANCIAL INTELLIGENCE',`<div class="select-list">${users.map(user=>`<button data-action="select-finance-user" data-id="${user.id}"><span>${initials(user.name)}</span><div><b>${esc(user.name)}</b><small>${user.email}</small></div><i>›</i></button>`).join('')}</div>`);return;}
  if(action==='select-finance-user'){ui.financeUserId=data.id;closeModal();render();return;}
  if(action==='ticket'){ui.selectedTicket=data.id;ui.ticketDetail=await api.getTicket(data.id);render();return;}
  if(action==='delete-announcement'){await api.deleteAnnouncement(data.id);toast('Broadcast removed','The broadcast was removed from the live announcement list.','pending');render();return;}
  if(action==='delete-ticket'){await api.deleteTicket(data.id);ui.selectedTicket=null;ui.ticketDetail=null;toast('Ticket deleted',`${data.id} was removed from the live support queue.`,'pending');render();return;}
  if(action==='setting-toggle'){const hidden=document.querySelector('#settings-form [name="cashbackEnabled"]');hidden.value=hidden.value==='true'?'false':'true';element.classList.toggle('on');return;}
  if(action==='funding-toggle'){const hidden=document.querySelector('#settings-form [name="automatedFundingEnabled"]');hidden.value=hidden.value==='true'?'false':'true';element.classList.toggle('on');return;}
  if(action==='add-manual-account'){document.querySelector('#manual-accounts-list')?.insertAdjacentHTML('beforeend',fundingAccountRows([{id:`manual-${Date.now()}`,bank_name:'',account_name:'',account_number:'',enabled:true}]));return;}
  if(action==='remove-manual-account'){element.closest('[data-manual-account-row]')?.remove();return;}
  if(action==='copy-webhook'){navigator.clipboard?.writeText((await api.getSettings()).webhook);toast('Webhook address unavailable','Webhook configuration is managed securely by the backend.','pending');return;}
  if(action==='open-admin'){openModal('Create administrator','CONSOLE ACCESS',`<form id="admin-form" class="form-row"><label>Full name<input name="name" required/></label><label>Email<input name="email" type="email" required/></label><label>Temporary password<input name="password" type="password" autocomplete="new-password" minlength="8" required/></label><button class="button primary" type="submit">Create administrator</button></form>`);return;}
  if(action==='audit-filter'){toast('Audit filters','Filter controls are not enabled yet.','pending');return;}
}
function openPlanModal(plan,group){const isEdit=Boolean(plan);openModal(isEdit?'Edit plan':'Add plan','SERVICE PRICING',`<form id="plan-form" class="form-row"><input type="hidden" name="id" value="${plan?.id||''}"/><input type="hidden" name="group" value="${plan?.group||group}"/><div class="form-row two"><label>Network<input name="network" value="${plan?.network||''}" required/></label><label>Plan name<input name="name" value="${plan?.name||''}" required/></label></div><div class="form-row two"><label>Customer price<input name="userPrice" type="number" value="${plan?.userPrice||''}" required/></label><label>Provider cost<input name="apiPrice" type="number" value="${plan?.apiPrice||''}" required/></label></div><label>Provider variation<input name="variation" value="${plan?.variation||''}" required/></label><button class="button primary" type="submit">${isEdit?'Save plan':'Create plan'} <span>→</span></button></form>`);}

async function handleSubmit(event){
  event.preventDefault(); const form=event.target; const data=Object.fromEntries(new FormData(form));
  try{
    if(form.id==='login-form'){await api.login(data.email,data.password);ui.loginError='';render();return;}
    if(form.id==='create-customer-form'){const user=await api.createUser(data);closeModal();toast('Customer created',`${user.name} has been enrolled.`);render();return;}
    if(form.id==='wallet-adjust-form'){const result=await api.adjustWallet(data);toast('Wallet updated',`${result.user.name} now has ${money(result.user[data.walletType==='main'?'main':data.walletType])}.`);render();return;}
    if(form.id==='network-form'){await api.updateNetwork(data.name,{discount:Number(data.discount),active:data.active==='true'});closeModal();toast('Network saved',`${data.name} availability and discount updated.`);render();return;}
    if(form.id==='plan-form'){if(data.id) await api.updatePlan(data.id,{network:data.network,name:data.name,userPrice:Number(data.userPrice),apiPrice:Number(data.apiPrice),variation:data.variation}); else await api.createPlan({group:data.group,network:data.network,name:data.name,userPrice:Number(data.userPrice),apiPrice:Number(data.apiPrice),variation:data.variation});closeModal();toast('Plan saved','Service pricing was updated in the live catalog.');render();return;}
    if(form.id==='ticket-reply-form'){await api.replyTicket(ui.selectedTicket,data.message);ui.ticketDetail=await api.getTicket(ui.selectedTicket);toast('Reply sent','The ticket thread and status were updated.');render();return;}
    if(form.id==='announcement-form'){await api.createAnnouncement(data);toast('Broadcast published','The customer announcement is active.');render();return;}
    if(form.id==='settings-form'){const accounts=[...form.querySelectorAll('[data-manual-account-row]')].map(row=>({id:`manual-${Math.random().toString(36).slice(2,9)}`,bank_name:row.querySelector('[data-account-field="bank_name"]')?.value.trim()||'',account_name:row.querySelector('[data-account-field="account_name"]')?.value.trim()||'',account_number:row.querySelector('[data-account-field="account_number"]')?.value.trim()||'',enabled:row.querySelector('[data-account-field="enabled"]')?.checked!==false}));const primary=accounts.find(account=>account.enabled&&account.bank_name&&account.account_name&&account.account_number)||accounts[0]||{};await api.updateSettings({cashbackEnabled:data.cashbackEnabled==='true',referralBudget:Number(data.referralBudget),referralCampaignStartAt:data.referralCampaignStartAt,referralCampaignEndAt:data.referralCampaignEndAt,automatedFundingEnabled:data.automatedFundingEnabled==='true',manualBankName:primary.bank_name||'',manualAccountName:primary.account_name||'',manualAccountNumber:primary.account_number||'',manualAccounts:accounts,manualWhatsappNumber:data.manualWhatsappNumber,manualFundingInstructions:data.manualFundingInstructions});toast('Platform controls saved','Funding mode and manual bank accounts were updated.');render();return;}
    if(form.id==='reconcile-form'){const result=await api.reconcile(data.reference,Boolean(data.force));toast(result.success?'Payment reconciled':'Payment not reconciled',result.message,result.success?'success':'danger');return;}
    if(form.id==='admin-form'){const admin=await api.createAdmin(data);closeModal();toast('Administrator created',`${admin.email} now has administrator access.`);render();return;}
    if(form.id==='profile-form'){await api.updateProfile({name:data.name,phone:data.phone});toast('Profile saved','Administrator identity updated.');render();return;}
    if(form.id==='password-form'){if(data.newPassword!==data.confirmPassword) throw new Error('New password and confirmation do not match.');await api.changePassword(data.currentPassword,data.newPassword);toast('Password updated','Use the new password on your next sign-in.');form.reset();return;}
    if(form.id==='new-ticket-form'){toast('Ticket created','New-ticket creation is documented for the future adapter.','pending');closeModal();return;}
    if(form.id==='service-form'){const service=await api.createService(data);toast('Service created',`${service.name} was added to the catalog.`,'success');closeModal();render();return;}
  }catch(error){if(form.id==='login-form'){ui.loginError=error.message;render();}else toast('Action could not be completed',error.message||'Please try again.','danger');}
}
function handleInput(event){ if(event.target.dataset.input==='customer-search'){ui.customerSearch=event.target.value;render();} if(event.target.dataset.input==='transaction-search'){ui.transactionSearch=event.target.value;render();} }
function handleChange(event){ const target=event.target;if(target.dataset.change==='transaction-status'){ui.transactionStatus=target.value;render();}if(target.dataset.change==='transaction-type'){ui.transactionType=target.value;render();}if(target.dataset.change==='finance-range'){ui.financeRange=target.value;render();}if(target.dataset.change==='finance-user'){ui.financeUserId=target.value;render();}if(target.dataset.change==='ticket-status'){api.updateTicket(ui.selectedTicket,target.value).then(async()=>{ui.ticketDetail=await api.getTicket(ui.selectedTicket);toast('Ticket status updated',`Ticket marked ${target.value}.`);render();}).catch(error=>toast('Ticket update failed',error.message,'danger'));} }
function handleClick(event){ const item=event.target.closest('[data-action],[data-tab]'); if(!item)return; if(item.dataset.tab){const key=item.dataset.tab;ui[`${key}Tab`]=item.dataset.value;render();return;} if(item.dataset.action) handleAction(item.dataset.action,item.dataset,item); }
document.addEventListener('click',handleClick); document.addEventListener('submit',handleSubmit); document.addEventListener('input',handleInput); document.addEventListener('change',handleChange);
render();
